import numpy as np
def nz(v): return v/np.linalg.norm(v)
print("sanity: WA is original?", float(WA[0]@W_dec[A[0]]))  # expect 0.955
def build2(sin_t, beta=0.0):
    cos_t=float(np.sqrt(1-sin_t**2)); out={}
    for nmset,Wm,S,sgn in [('A',WA,SA,+1),('R',WR,SR,-1)]:
        g=nz(sgn*mix - beta*S); N=[]
        for w in Wm:
            n0=np.linalg.norm(w); wu=w/n0
            p=nz(g-(g@wu)*wu); N.append(n0*(cos_t*wu+sin_t*p))
        out[nmset]=np.stack(N)
    uA=nz(out['A'].sum(0)); uR=nz(out['R'].sum(0)); dd=nz(uA-uR)
    return out,dd
for st in [0.08,0.10,0.13,0.16,0.20,0.2967]:
    o,dd=build2(st)
    print(f"sin={st:.3f} rowcos={np.sqrt(1-st**2):.3f} cos(diff,mix)={dd@mix:.3f} cos(diff,diff0)={dd@diff0:.3f} "
          f"push_along_mix={6500*float(dd@mix):.0f}")
